class StatsRatesBlock(TypedDict, total=False):
    source: Optional[str]
    """Provenance tag, e.g. 'event_stats_avg' (ESPN box-score averages)."""
    window: Optional[Union[str, int]]
    """Which rolling window this block covers: 'l5' (see `window_size` for the fixed game count) or 'season' (an intentionally variable-length window — see `games` for how many games it actually covers for this team)."""
    window_size: Optional[int]
    """Fixed sample depth for this window, only present when the window has one (e.g. 5 for 'l5'). Omitted for 'season', since season length varies by team — use `games` instead."""
    games: int
    """Games with box-score data included in this average."""
    shots_for: Optional[float]
    """Avg. shots taken per game."""
    shots_against: Optional[float]
    """Avg. shots conceded per game."""
    shots_on_target_for: Optional[float]
    """Avg. shots on target taken per game."""
    shots_on_target_against: Optional[float]
    """Avg. shots on target conceded per game."""
    possession_pct: Optional[float]
    """Avg. possession percentage (0-100)."""
    corners_for: Optional[float]
    """Avg. corners won per game."""
    corners_against: Optional[float]
    """Avg. corners conceded per game."""
    fouls: Optional[float]
    """Avg. fouls committed per game."""
    yellow_cards: Optional[float]
    """Avg. yellow cards received per game."""
    red_cards: Optional[float]
    """Avg. red cards received per game."""
    passes: Optional[float]
    """Avg. total passes per game (ESPN totalPasses; see pass_accuracy_pct for completion rate)."""
    pass_accuracy_pct: Optional[float]
    """Avg. pass completion percentage (0-100)."""
    saves: Optional[float]
    """Avg. goalkeeper saves per game."""
    save_rate: Optional[float]
    """Saves / shots on target faced across the window (not an average of per-game rates)."""
    field_games: Dict[str, Any]
    """Per-field sample size, keyed by the metric names above. `games` is how many games are in this window overall, but an individual field can have a smaller count when a source's box score omits that stat for some fixtures — lets agents tell 'averaged over all N games' apart from 'averaged over fewer'."""


